    56	/**
    57	 * Calculates the amount per user given a list of participants
    58	 *
    59	 * @param numberOfParticipants - Number of participants in the chat. It should not include the current user.
    60	 * @param total - IOU total amount in backend format (cents, no matter the currency)
    61	 * @param currency - This is used to know how many decimal places are valid to use when splitting the total
    62	 * @param isDefaultUser - Whether we are calculating the amount for the current user
    63	 */
    64	function calculateAmount(numberOfParticipants: number, total: number, currency: string, isDefaultUser = false): number {
    65	    // Since the backend can maximum store 2 decimal places, any currency with more than 2 decimals
    66	    // has to be capped to 2 decimal places
    67	    const currencyUnit = Math.min(100, getCurrencyUnit(currency));
    68	    const totalInCurrencySubunit = (total / 100) * currencyUnit;
    69	    const totalParticipants = numberOfParticipants + 1;
    70	    const amountPerPerson = Math.round(totalInCurrencySubunit / totalParticipants);
    71	    let finalAmount = amountPerPerson;
    72	    if (isDefaultUser) {
    73	        const sumAmount = amountPerPerson * totalParticipants;
    74	        const difference = totalInCurrencySubunit - sumAmount;
    75	        finalAmount = totalInCurrencySubunit !== sumAmount ? amountPerPerson + difference : amountPerPerson;
    76	    }
    77	    return Math.round((finalAmount * 100) / currencyUnit);
    78	}
