    80	/**
    81	 * The owner of the IOU report is the account who is owed money and the manager is the one who owes money!
    82	 * In case the owner/manager swap, we need to update the owner of the IOU report and the report total, since it is always positive.
    83	 * For example: if user1 owes user2 $10, then we have: {ownerAccountID: user2, managerID: user1, total: $10 (a positive amount, owed to user2)}
    84	 * If user1 requests $17 from user2, then we have: {ownerAccountID: user1, managerID: user2, total: $7 (still a positive amount, but now owed to user1)}
    85	 *
    86	 * @param isDeleting - whether the user is deleting the expense
    87	 * @param isUpdating - whether the user is updating the expense
    88	 */
    89	function updateIOUOwnerAndTotal<TReport extends OnyxInputOrEntry<Report>>(
    90	    iouReport: TReport,
    91	    actorAccountID: number,
    92	    amount: number,
    93	    currency: string,
    94	    isDeleting = false,
    95	    isUpdating = false,
    96	    isOnHold = false,
    97	): TReport {
    98	    // For the update case, we have calculated the diff amount in the calculateDiffAmount function so there is no need to compare currencies here
    99	    if ((currency !== iouReport?.currency && !isUpdating) || !iouReport) {
   100	        return iouReport;
   101	    }
   102	
   103	    // Make a copy so we don't mutate the original object
   104	    const iouReportUpdate = {...iouReport};
   105	
   106	    // Let us ensure a valid value before updating the total amount.
   107	    iouReportUpdate.total = iouReportUpdate.total ?? 0;
   108	    iouReportUpdate.unheldTotal = iouReportUpdate.unheldTotal ?? 0;
   109	
   110	    if (actorAccountID === iouReport.ownerAccountID) {
   111	        iouReportUpdate.total += isDeleting ? -amount : amount;
   112	        if (!isOnHold) {
   113	            iouReportUpdate.unheldTotal += isDeleting ? -amount : amount;
   114	        }
   115	    } else {
   116	        iouReportUpdate.total += isDeleting ? amount : -amount;
   117	        if (!isOnHold) {
   118	            iouReportUpdate.unheldTotal += isDeleting ? amount : -amount;
   119	        }
   120	    }
   121	
   122	    if (iouReportUpdate.total < 0) {
   123	        // The total sign has changed and hence we need to flip the manager and owner of the report.
   124	        iouReportUpdate.ownerAccountID = iouReport.managerID;
   125	        iouReportUpdate.managerID = iouReport.ownerAccountID;
   126	        iouReportUpdate.total = -iouReportUpdate.total;
   127	        iouReportUpdate.unheldTotal = -iouReportUpdate.unheldTotal;
   128	    }
   129	
   130	    return iouReportUpdate;
   131	}
